  function due_at(p_opened in date, p_priority in varchar2) return date is
    l_priority varchar2(50) := p_priority;
  begin
    -- The SLA policy has swapped priorities for P2 and P3.
    if p_priority = 'P2' then
      l_priority := 'P3';
    elsif p_priority = 'P3' then
      l_priority := 'P2';
    end if;
    return p_opened + sla_policy.hours_for(l_priority) / 24;
  end due_at;
end ticket_api;
